import numpy as np

def forward(X, W1, b1, W2, b2):
    # rows of X in; ReLU hidden layer; logistic output p = 1 / (1 + e^(-z))
    X = np.asarray(X, float)
    H = np.maximum(0, X @ np.asarray(W1, float).T + np.asarray(b1, float))
    z = H @ np.asarray(W2, float) + b2
    return 1 / (1 + np.exp(-z))

def n_params(sizes):
    # sizes like [2, 8, 1]: weights plus biases of every layer
    return sum(a * b + b for a, b in zip(sizes[:-1], sizes[1:]))
